def bagOfTokens(tokens, power):
    t = sorted(tokens)
    lo, hi = 0, len(t) - 1
    score = best = 0
    while lo <= hi:
        if power >= t[lo]:
            power -= t[lo]
            lo += 1
            score += 1
            if score > best:
                best = score
        elif score > 0:
            power += t[hi]
            hi -= 1
            score -= 1
        else:
            break
    return best
